import{_ as s,o as i,c as a,an as t}from"./chunks/framework.CQDbILCq.js";const u=JSON.parse('{"title":"OSCP · Active Directory","description":"Parcours de révision Active Directory, inventaire des notions et commandes de vérification.","frontmatter":{"title":"OSCP · Active Directory","description":"Parcours de révision Active Directory, inventaire des notions et commandes de vérification."},"headers":[],"relativePath":"oscp/active-directory.md","filePath":"oscp/active-directory.md"}'),n={name:"oscp/active-directory.md"};function r(l,e,o,d,p,c){return i(),a("div",null,e[0]||(e[0]=[t('<h1 id="active-directory" tabindex="-1">Active Directory <a class="header-anchor" href="#active-directory" aria-label="Permalink to &quot;Active Directory&quot;">​</a></h1><p>Parcours de révision à utiliser dans un laboratoire autorisé. Les rubriques suivent un ordre d’apprentissage, pas une chaîne d’exploitation automatique.</p><h2 id="fondamentaux" tabindex="-1">Fondamentaux <a class="header-anchor" href="#fondamentaux" aria-label="Permalink to &quot;Fondamentaux&quot;">​</a></h2><p>Avant de lire les résultats, identifier le domaine, les contrôleurs de domaine, les utilisateurs, les groupes, les ordinateurs, les OU, les GPO et les relations entre domaines. Comprendre la différence entre LDAP, SMB, DNS, NTLM et Kerberos.</p><p><a href="./ad-theorie">Théorie Active Directory</a></p><h2 id="decouverte-du-domaine" tabindex="-1">Découverte du domaine <a class="header-anchor" href="#decouverte-du-domaine" aria-label="Permalink to &quot;Découverte du domaine&quot;">​</a></h2><h3 id="reconnaissance-reseau" tabindex="-1">Reconnaissance réseau <a class="header-anchor" href="#reconnaissance-reseau" aria-label="Permalink to &quot;Reconnaissance réseau&quot;">​</a></h3><p>Les exemples utilisent les adresses réservées à la documentation <code>192.0.2.0/24</code> et le domaine <code>example.test</code>. Remplacer ces valeurs uniquement par celles du laboratoire autorisé.</p><h4 id="decouvrir-les-hotes-actifs" tabindex="-1">Découvrir les hôtes actifs <a class="header-anchor" href="#decouvrir-les-hotes-actifs" aria-label="Permalink to &quot;Découvrir les hôtes actifs&quot;">​</a></h4><p class="oscp-command-note">Repérer les machines joignables sur le réseau du laboratoire sans scanner leurs ports. La notation `-sP -p` de la mind map est remplacée par `-sn`, qui correspond à la découverte d’hôtes.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sn</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 192.0.2.0/28</span></span></code></pre></div><h4 id="identifier-les-ports-tcp-les-plus-courants" tabindex="-1">Identifier les ports TCP les plus courants <a class="header-anchor" href="#identifier-les-ports-tcp-les-plus-courants" aria-label="Permalink to &quot;Identifier les ports TCP les plus courants&quot;">​</a></h4><p class="oscp-command-note">Effectuer un premier inventaire des 50 ports les plus fréquents et des versions des services ouverts.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -Pn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --top-ports</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 50</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --open</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 192.0.2.10</span></span></code></pre></div><h4 id="examiner-les-ports-tcp-courants" tabindex="-1">Examiner les ports TCP courants <a class="header-anchor" href="#examiner-les-ports-tcp-courants" aria-label="Permalink to &quot;Examiner les ports TCP courants&quot;">​</a></h4><p class="oscp-command-note">Identifier les services sur les ports TCP par défaut et enregistrer les résultats dans les trois formats Nmap. Les scripts par défaut ne sont à utiliser que dans le périmètre autorisé.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -Pn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sC</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oA</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ad-tcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 192.0.2.10</span></span></code></pre></div><h4 id="examiner-tous-les-ports-tcp" tabindex="-1">Examiner tous les ports TCP <a class="header-anchor" href="#examiner-tous-les-ports-tcp" aria-label="Permalink to &quot;Examiner tous les ports TCP&quot;">​</a></h4><p class="oscp-command-note">Étendre l’inventaire aux 65 535 ports TCP lorsque le premier contrôle ne suffit pas.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -Pn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sC</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oA</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ad-tcp-complet</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 192.0.2.10</span></span></code></pre></div><h4 id="examiner-les-services-udp" tabindex="-1">Examiner les services UDP <a class="header-anchor" href="#examiner-les-services-udp" aria-label="Permalink to &quot;Examiner les services UDP&quot;">​</a></h4><p class="oscp-command-note">Compléter le relevé TCP par un inventaire UDP. Ce contrôle peut être plus lent et nécessiter des privilèges élevés.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sU</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sC</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -sV</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -oA</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ad-udp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 192.0.2.10</span></span></code></pre></div><h4 id="identifier-les-services-smb" tabindex="-1">Identifier les services SMB <a class="header-anchor" href="#identifier-les-services-smb" aria-label="Permalink to &quot;Identifier les services SMB&quot;">​</a></h4><p class="oscp-command-note">Recenser les machines qui répondent sur SMB avec NetExec, sans fournir d’identifiants.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nxc</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> smb</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 192.0.2.0/28</span></span></code></pre></div><h4 id="verifier-les-versions-du-protocole-smb" tabindex="-1">Vérifier les versions du protocole SMB <a class="header-anchor" href="#verifier-les-versions-du-protocole-smb" aria-label="Permalink to &quot;Vérifier les versions du protocole SMB&quot;">​</a></h4><p class="oscp-command-note">La mind map propose des scripts de vulnérabilité SMB génériques. Pour ce premier contrôle, utiliser un script ciblé de lecture des protocoles pris en charge ; SMBv1 est notamment une configuration à examiner.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 139,445</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --script</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> smb-protocols</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 192.0.2.10</span></span></code></pre></div><h3 id="identification-du-controleur-de-domaine" tabindex="-1">Identification du contrôleur de domaine <a class="header-anchor" href="#identification-du-controleur-de-domaine" aria-label="Permalink to &quot;Identification du contrôleur de domaine&quot;">​</a></h3><h4 id="afficher-la-configuration-reseau-linux" tabindex="-1">Afficher la configuration réseau Linux <a class="header-anchor" href="#afficher-la-configuration-reseau-linux" aria-label="Permalink to &quot;Afficher la configuration réseau Linux&quot;">​</a></h4><p class="oscp-command-note">Vérifier l’adresse IP, la passerelle et les serveurs DNS de l’interface. Remplacer eth0 par l’interface réelle. NetworkManager doit être présent.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmcli</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> dev</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> show</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> eth0</span></span></code></pre></div><h4 id="localiser-les-controleurs-de-domaine-par-dns" tabindex="-1">Localiser les contrôleurs de domaine par DNS <a class="header-anchor" href="#localiser-les-controleurs-de-domaine-par-dns" aria-label="Permalink to &quot;Localiser les contrôleurs de domaine par DNS&quot;">​</a></h4><p class="oscp-command-note">Interroger les enregistrements SRV LDAP du domaine. Utiliser le serveur DNS du laboratoire et remplacer example.test par le domaine étudié.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nslookup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -type=SRV</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> _ldap._tcp.dc._msdcs.example.test</span></span></code></pre></div><h4 id="identifier-les-serveurs-kerberos" tabindex="-1">Identifier les serveurs Kerberos <a class="header-anchor" href="#identifier-les-serveurs-kerberos" aria-label="Permalink to &quot;Identifier les serveurs Kerberos&quot;">​</a></h4><p class="oscp-command-note">Rechercher les hôtes du laboratoire qui exposent le port TCP 88. Un port 88 ouvert est un indice, pas une preuve qu’un hôte est un contrôleur de domaine.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">nmap</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> 88</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> --open</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> 192.0.2.0/28</span></span></code></pre></div><h3 id="interroger-les-metadonnees-ldap" tabindex="-1">Interroger les métadonnées LDAP <a class="header-anchor" href="#interroger-les-metadonnees-ldap" aria-label="Permalink to &quot;Interroger les métadonnées LDAP&quot;">​</a></h3><p>Lecture de la RootDSE sans modification de l’annuaire. Adapter le nom du serveur au laboratoire.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">ldapsearch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -x</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> ldap://dc.example.test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> base</span></span></code></pre></div><p>À connaître dans la mind map : découverte des services, DNS et transferts de zone, accès SMB invité ou anonyme, LDAP anonyme, visibilité des comptes, PXE, TimeRoasting, poisoning et coercition. Ces derniers sujets sont des risques à étudier dans leur contexte.</p><p><a href="./ad-enumeration">Énumération Active Directory</a></p><h2 id="comptes-et-authentification" tabindex="-1">Comptes et authentification <a class="header-anchor" href="#comptes-et-authentification" aria-label="Permalink to &quot;Comptes et authentification&quot;">​</a></h2><p>Distinguer un identifiant connu, un compte authentifié, les droits locaux et les droits du domaine. Un identifiant valide n’implique pas de privilège administratif.</p><h3 id="lire-la-politique-de-mot-de-passe-du-domaine" tabindex="-1">Lire la politique de mot de passe du domaine <a class="header-anchor" href="#lire-la-politique-de-mot-de-passe-du-domaine" aria-label="Permalink to &quot;Lire la politique de mot de passe du domaine&quot;">​</a></h3><p>Depuis PowerShell avec le module ActiveDirectory (RSAT), afficher les règles par défaut : longueur, historique et seuil de verrouillage notamment.</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Get-ADDefaultDomainPasswordPolicy</span></span></code></pre></div><h3 id="lire-les-politiques-de-mot-de-passe-affinees" tabindex="-1">Lire les politiques de mot de passe affinées <a class="header-anchor" href="#lire-les-politiques-de-mot-de-passe-affinees" aria-label="Permalink to &quot;Lire les politiques de mot de passe affinées&quot;">​</a></h3><p>Afficher les politiques distinctes de la politique par défaut, lorsqu’elles existent.</p><div class="language-powershell vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;">Get-ADFineGrainedPasswordPolicy</span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">Filter </span><span style="--shiki-light:#D73A49;--shiki-dark:#FF7B72;">*</span></span></code></pre></div><p>La mind map distingue notamment les formats LM, NT, NTLMv1, NTLMv2, Kerberos TGS et AS-REP, MSCache 2, PXE et Timeroast. Elle traite aussi le password spraying, l’AS-REP Roasting, le Kerberoasting, les relais NTLM/Kerberos et les risques d’interception. Un hash, un ticket et un mot de passe en clair ne sont pas interchangeables.</p><h2 id="objets-permissions-et-delegations" tabindex="-1">Objets, permissions et délégations <a class="header-anchor" href="#objets-permissions-et-delegations" aria-label="Permalink to &quot;Objets, permissions et délégations&quot;">​</a></h2><p>Étudier les ACL/ACE des utilisateurs, groupes, ordinateurs et OU, les GPO, les comptes gMSA, LAPS et DNS Admins. Comprendre la portée des droits de réplication, DCSync et des modifications de <code>msDS-KeyCredentialLink</code>.</p><p>Délégations Kerberos : distinguer unconstrained delegation, constrained delegation, resource-based constrained delegation et S4U2self. Examiner les relations d’autorisation sans confondre un droit sur un objet et une permission administrative générale.</p><h2 id="services-et-configurations-sensibles" tabindex="-1">Services et configurations sensibles <a class="header-anchor" href="#services-et-configurations-sensibles" aria-label="Permalink to &quot;Services et configurations sensibles&quot;">​</a></h2><h3 id="ad-cs" tabindex="-1">AD CS <a class="header-anchor" href="#ad-cs" aria-label="Permalink to &quot;AD CS&quot;">​</a></h3><p>Distinguer les modèles de certificat, l’autorité de certification (CA), les permissions sur les objets PKI, le Web Enrollment, les ACL et le certificate mapping. Un certificat d’authentification ne doit pas être confondu avec un simple certificat TLS.</p><h3 id="sccm" tabindex="-1">SCCM <a class="header-anchor" href="#sccm" aria-label="Permalink to &quot;SCCM&quot;">​</a></h3><p>Identifier les rôles du site, les clients, la base de données, les permissions d’administration et les paramètres de déploiement. Les catégories de la mind map comprennent les risques liés aux identifiants, à l’élévation, à la prise de contrôle du site et au nettoyage.</p><h3 id="services-et-vulnerabilites" tabindex="-1">Services et vulnérabilités <a class="header-anchor" href="#services-et-vulnerabilites" aria-label="Permalink to &quot;Services et vulnérabilités&quot;">​</a></h3><p>La mind map couvre Exchange, GLPI, Veeam, MSSQL, Java RMI, désérialisation Java, Log4Shell, Tomcat/JBoss et les services exposés. Elle cite notamment MS17-010, Zerologon (signalé comme dangereux), MS14-025, MS14-068, PrivExchange, noPac, PrintNightmare, Certifried et ProxyNotShell. Vérifier l’applicabilité de chaque CVE, la version, les correctifs et les règles du laboratoire avant toute validation.</p><h2 id="privileges-locaux-et-acces-distants" tabindex="-1">Privilèges locaux et accès distants <a class="header-anchor" href="#privileges-locaux-et-acces-distants" aria-label="Permalink to &quot;Privilèges locaux et accès distants&quot;">​</a></h2><p>Distinguer les comptes de service, SeImpersonatePrivilege, UAC, AppLocker, les configurations WebDAV et les informations présentes dans les fichiers. Étudier les risques liés à LSASS, SAM, LSA et DPAPI, sans assimiler un accès local à un droit sur l’ensemble du domaine.</p><p>Pour les accès distants, distinguer les protocoles, le compte et le contexte d’authentification : mot de passe, NT hash, ticket Kerberos, certificat PFX, MSSQL et SOCKS. Les droits de connexion varient selon le service et la machine.</p><ul><li><a href="./privileges-windows">Privilèges Windows</a></li><li><a href="./ad-techniques">Techniques Active Directory</a></li><li><a href="./ad-lateral">Mouvement latéral Active Directory</a></li></ul><h2 id="relations-d-approbation" tabindex="-1">Relations d’approbation <a class="header-anchor" href="#relations-d-approbation" aria-label="Permalink to &quot;Relations d’approbation&quot;">​</a></h2><h3 id="lire-les-relations-d-approbation-windows" tabindex="-1">Lire les relations d’approbation Windows <a class="header-anchor" href="#lire-les-relations-d-approbation-windows" aria-label="Permalink to &quot;Lire les relations d’approbation Windows&quot;">​</a></h3><p>Depuis un poste Windows joint au domaine, afficher les domaines approuvés visibles par le poste.</p><div class="language-cmd vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E6EDF3;">nltest.exe /trusted_domains</span></span></code></pre></div><p>La mind map distingue les trusts parent/enfant, les trusts externes et les liens MSSQL. Étudier les SID de domaine, le sens de la relation, sa transitivité et les frontières d’autorisation.</p><h2 id="risques-lies-aux-privileges-de-domaine-et-a-la-persistance" tabindex="-1">Risques liés aux privilèges de domaine et à la persistance <a class="header-anchor" href="#risques-lies-aux-privileges-de-domaine-et-a-la-persistance" aria-label="Permalink to &quot;Risques liés aux privilèges de domaine et à la persistance&quot;">​</a></h2><p>La mind map présente les risques concernant NTDS.dit, les clés de sauvegarde, les droits de réplication, les modifications d’ACL, DCShadow, les comptes administrateurs et DSRM. Elle recense aussi Golden/Silver/Diamond/Sapphire Ticket, Golden Certificate, Skeleton Key et Custom SSP. Ces notions sont à comprendre en termes d’impact, de détection et de remédiation. Elles ne constituent pas un objectif systématique d’un examen OSCP.</p><h2 id="rapport-et-revision" tabindex="-1">Rapport et révision <a class="header-anchor" href="#rapport-et-revision" aria-label="Permalink to &quot;Rapport et révision&quot;">​</a></h2><p>Documenter le périmètre, le contexte du compte utilisé, les observations, les preuves, les limites de la validation et les remédiations. Consulter les règles OffSec en vigueur avant l’examen.</p><p><a href="./rapport">Rédaction de rapports</a> · <a href="./references">Références</a></p><h2 id="mind-map-complete" tabindex="-1">Mind map complète <a class="header-anchor" href="#mind-map-complete" aria-label="Permalink to &quot;Mind map complète&quot;">​</a></h2><p><a href="https://orange-cyberdefense.github.io/ocd-mindmaps/img/mindmap_ad_dark_classic_2025.03.excalidraw.svg" target="_blank" rel="noreferrer">Active Directory Mindmap v2025.03 - Orange Cyberdefense</a></p><p>Cette fiche est une synthèse de révision en français. La mind map originale contient l’intégralité des notes, exemples et commandes dans leur contexte. Les exemples de vérification ci-dessus en sont adaptés ; ils n’ont pas été exécutés ici.</p><p>Projet original : <a href="https://github.com/Orange-Cyberdefense/ocd-mindmaps" target="_blank" rel="noreferrer">ocd-mindmaps</a> · Mayfly et contributeurs · GPL-3.0.</p>',81)]))}const m=s(n,[["render",r]]);export{u as __pageData,m as default};
